test "t13 hashmap distinct" {
    const words = [_][]const u8{ "a", "b", "a", "c", "b", "a" };
    try std.testing.expectEqual(@as(usize, 3), try distinctCount(std.testing.allocator, &words));
    try std.testing.expectEqual(@as(usize, 0), try distinctCount(std.testing.allocator, &.{}));
    const same = [_][]const u8{ "ab", "a" ++ "b" };
    try std.testing.expectEqual(@as(usize, 1), try distinctCount(std.testing.allocator, &same));
}
